#!/system/bin/sh

# HMA-OSS SUSFS sus_path sync script
#
# This script is shipped inside the manager APK (assets/susfs_sync.sh) and
# pushed to /data/adb/hma_susfs/sync.sh by SusfsSyncer, then executed as root.
# It applies the package/path lists generated by the manager app so the disk
# (path) layer hiding matches the API layer hiding.
#
# It is idempotent and silently skips everything when ksu_susfs is missing.

SUSFS_DIR=/data/adb/hma_susfs
PKGS_FILE="$SUSFS_DIR/pkgs.txt"
EXTRA_FILE="$SUSFS_DIR/extra_paths.txt"
TARGETS_FILE="$SUSFS_DIR/targets.txt"

# ABK: see hmaoss.sh - uid hiding is global, so only the detector target gets it.
UID_HIDE_TARGET="${UID_HIDE_TARGET:-com.chunqiunativecheck}"

# ABK: ONE hard-coded path. KernelSU's ksud re-links
# /data/adb/ksu/bin/ksu_susfs to its multi-call applet, which rejects the
# per-UID / per-target subcommands, and PATH lookup can hit that applet too.
# Neither is ever used here: only the module's private copy.
KSU_SUSFS=/data/adb/hma_susfs/bin/ksu_susfs

if [ ! -x "$KSU_SUSFS" ]; then
    _mod=/data/adb/modules/hma_oss_zygisk/susfs/ksu_susfs
    if [ -f "$_mod" ]; then
        mkdir -p /data/adb/hma_susfs/bin 2>/dev/null
        cp -f "$_mod" "$KSU_SUSFS" 2>/dev/null
        chmod 755 "$KSU_SUSFS" 2>/dev/null
    fi
fi

if [ ! -x "$KSU_SUSFS" ]; then
    echo "SUSFS_SYNC_ERROR: $KSU_SUSFS is missing (the ksud applet is not accepted)"
    exit 2
fi

# Self-test: the tool MUST expose the per-target subcommands.
if ! "$KSU_SUSFS" 2>&1 | grep -q 'add_hidden_uid_from'; then
    echo "SUSFS_SYNC_ERROR: $KSU_SUSFS does not support add_hidden_uid_from"
    exit 3
fi

# ABK STATE_DICT_ABK: the runtime dictionary of what is already applied.
#
# A sync APPENDS only the newly configured (uid, path) pairs instead of
# re-sending the whole list, because the kernel keeps every entry until reboot
# and re-applying thousands of pairs costs time.  The file is a plain
# dictionary, one "<uid>|<path>" line each.
#
#   --reset   drop the dictionary and apply everything again (used on boot,
#             where the kernel has forgotten all entries)
#   (default) append only what is missing
STATE_FILE="$SUSFS_DIR/state.tsv"
STATE_MODE="append"
case "${1:-}" in
    --reset) STATE_MODE="reset" ;;
esac
[ "${SUSFS_STATE_RESET:-0}" = "1" ] && STATE_MODE="reset"

mkdir -p "$SUSFS_DIR" 2>/dev/null
[ "$STATE_MODE" = "reset" ] && : > "$STATE_FILE" 2>/dev/null
[ -f "$STATE_FILE" ] || : > "$STATE_FILE" 2>/dev/null
STATE_BLOB="$(cat "$STATE_FILE" 2>/dev/null)"
STATE_SKIPPED=0

# The lookup runs in-process over the whole dictionary (no fork per pair), so a
# full pass over a few thousand entries stays fast.
state_has() {
    case "$STATE_BLOB" in
        *"
$1"*) return 0 ;;
    esac
    return 1
}

state_add() {
    printf '%s\n' "$1" >> "$STATE_FILE" 2>/dev/null
    STATE_BLOB="$STATE_BLOB
$1"
}

# ABK: apply one (uid, path) pair unless the dictionary already has it.
susfs_apply_once() {
    _mode="$1"
    _path="$2"
    _uid="$3"
    _key="$_mode|$_uid|$_path"

    if state_has "$_key"; then
        STATE_SKIPPED=$((STATE_SKIPPED + 1))
        return 0
    fi

    if [ "$_mode" = "hide_from" ]; then
        "$KSU_SUSFS" add_sus_path_hide_from "$_path" "$_uid" >/dev/null 2>&1 || return 1
    else
        "$KSU_SUSFS" add_sus_path_loop "$_path" "$_uid" >/dev/null 2>&1 || return 1
    fi

    state_add "$_key"
    return 0
}

# ABK per-target helper: hide a path from ONE target uid only (kernel 'hide_from').
add_hide_from() {
    _path="$1"
    _uid="$2"

    [ -z "$_path" ] && return 0
    [ -e "$_path" ] || return 0

    susfs_apply_once hide_from "$_path" "$_uid"
    return 0
}

# ABK per-target sync: targets.txt lines are "<targetPkg><TAB><hiddenPkg>".
sync_target_hides() {
    _targets_file="$1"
    [ -s "$_targets_file" ] || return 0

    _tab="$(printf '\t')"

    while IFS="$_tab" read -r _target _hidden _mode; do
        case "$_target" in ""|"#"*) continue ;; esac
        case "$_hidden" in ""|"#"*) continue ;; esac

        # ABK: "|| true" keeps set -e from aborting the loop on packages that
        # are not installed (stat fails), which used to skip later targets.
        _tuid="$(stat -c %u "/data/user/0/$_target" 2>/dev/null)" || true
        [ -n "$_tuid" ] || _tuid="$(stat -c %u "/data/data/$_target" 2>/dev/null)" || true
        [ -z "$_tuid" ] && continue

        # ABK: per-target uid hiding - one private (hidden_uid, target_uid)
        # pair per line, so no other app's view is affected.
        _huid="$(stat -c %u "/data/user/0/$_hidden" 2>/dev/null)" || true
        # ABK SELF_VIEW_TARGET_ABK: an app never hides its own paths from itself
        [ -n "$_huid" ] && [ "$_tuid" = "$_huid" ] && continue
        if [ -n "$_huid" ] && [ -n "$_tuid" ]; then
            "$KSU_SUSFS" add_hidden_uid_from "$_huid" "$_tuid" >/dev/null 2>&1 || true
        fi

        if [ "$_mode" = "data" ]; then
            _paths="/data/user/0/$_hidden /data/user_de/0/$_hidden /data/data/$_hidden /data_mirror/data_ce/null/$_hidden /data_mirror/data_de/null/$_hidden /storage/emulated/0/Android/data/$_hidden /data/media/0/Android/data/$_hidden"
        else
            _paths="/data/user/0/$_hidden /data/user_de/0/$_hidden /data/data/$_hidden /data_mirror/data_ce/null/$_hidden /data_mirror/data_de/null/$_hidden /storage/emulated/0/Android/data/$_hidden /data/media/0/Android/data/$_hidden /data/app/*/$_hidden-* /data/app/*/$_hidden"
        fi

        for _p in $_paths
        do
            add_hide_from "$_p" "$_tuid"
        done
    done < "$_targets_file"

    return 0
}
add_sus_path() {
    _path="$1"
    _uid="$2"
    _loop="$3"

    [ -z "$_path" ] && return 0

    # ABK SUS_PATH_LOOP_MODE_ABK: every plain hide-list path goes through the
    # loop variant; the kernel re-resolves and re-flags it on every app spawn,
    # so an evicted inode or a re-created data dir keeps being hidden.  The
    # loop form also accepts paths that do not exist yet.
    susfs_apply_once loop "$_path" "$_uid"
    return 0
}

sync_pkg() {
    _pkg="$1"

    [ -z "$_pkg" ] && return 0

    _uid="$(stat -c %u "/data/user/0/$_pkg" 2>/dev/null)"
    [ -z "$_uid" ] && _uid="-1"

    add_sus_path "/data/user/0/$_pkg" "$_uid" 0
    add_sus_path "/data/user_de/0/$_pkg" "$_uid" 0
    add_sus_path "/data/data/$_pkg" "$_uid" 0
    add_sus_path "/data_mirror/data_ce/null/$_pkg" "$_uid" 0
    add_sus_path "/data_mirror/data_de/null/$_pkg" "$_uid" 0

    for _p in /mnt/asec/"$_pkg"* /mnt/obb/"$_pkg"*; do
        add_sus_path "$_p" "$_uid" 0
    done

    # ABK (all-in mode): hide the install dir and external-storage dir too.
    # This CAN degrade launcher icons for the listed apps; that is accepted for
    # now (the detector enumerates /data/app and Android/data natively).
    for _p in /data/app/*/"$_pkg"-* /data/app/*/"$_pkg" \
              "/storage/emulated/0/Android/data/$_pkg" \
              "/data/media/0/Android/data/$_pkg"; do
        add_sus_path "$_p" "$_uid" 0
    done

    return 0
}

if [ -s "$PKGS_FILE" ]; then
    while IFS= read -r _line; do
        case "$_line" in
            ""|"#"*) continue ;;
        esac

        sync_pkg "$_line"
    done < "$PKGS_FILE"
fi

# ABK EXTRA_PKG_EXPAND_ABK: the "<PKG>" placeholder used to expand over
# pkgs.txt only, but in HMA's per-target mode pkgs.txt stays empty (the hide
# relations live in targets.txt as "<target>\t<hidden>"), so every
# "/data/data/<PKG>" style extra path silently did nothing.
hidden_pkgs() {
    {
        [ -s "$SUSFS_DIR/targets.txt" ] && cut -f2 "$SUSFS_DIR/targets.txt" 2>/dev/null
        [ -s "$SUSFS_DIR/pkgs.txt" ] && cat "$SUSFS_DIR/pkgs.txt" 2>/dev/null
    } | sed 's/[[:space:]]*$//' | grep -v '^[[:space:]]*$' | grep -v '^#' | sort -u
}

# ABK EXTRA_PATH_SCOPE_ABK: an extra path must be hidden only from the apps
# that are configured to hide things (targets.txt column 1), never from the
# whole system: the hidden app keeps its own view and whitelisted apps keep a
# complete view (A->B visible, C->B hidden).
hidden_targets() {
    [ -s "$SUSFS_DIR/targets.txt" ] && cut -f1 "$SUSFS_DIR/targets.txt" 2>/dev/null \
        | sed 's/[[:space:]]*$//' | grep -v '^[[:space:]]*$' | grep -v '^#' | sort -u
}

apply_extra_path_for_targets() {
    _path="$1"
    _targets="$2"

    [ -n "$_path" ] || return 0
    [ -e "$_path" ] || return 0
    [ -n "$_targets" ] || return 0

    # ABK SELF_VIEW_ABK: never hide a path from the app that owns it - the
    # detector is also a target (it hides other apps), so without this guard
    # /data/data/<detector> gets denied for the detector itself and the app
    # cannot read its own data (crashes on its onboarding screen).
    _owner_uid="$(stat -c %u "$_path" 2>/dev/null)"

    printf '%s\n' "$_targets" | while IFS= read -r _tpkg; do
        [ -n "$_tpkg" ] || continue
        _tuid="$(stat -c %u "/data/user/0/$_tpkg" 2>/dev/null)"
        [ -n "$_tuid" ] || continue
        [ "$_tuid" = "$_owner_uid" ] && continue
        susfs_apply_once hide_from "$_path" "$_tuid" || true
    done
}

if [ -s "$EXTRA_FILE" ]; then
    _targets="$(hidden_targets)"
    while IFS= read -r _line; do
        case "$_line" in
            ""|"#"*) continue ;;
        esac

        case "$_line" in
            *"<PKG>"*)
                _pkg_list="$(hidden_pkgs)"
                if [ -n "$_pkg_list" ]; then
                    printf '%s\n' "$_pkg_list" | while IFS= read -r _pkg; do
                        [ -n "$_pkg" ] || continue

                        _expanded="$(printf '%s' "$_line" | sed "s|<PKG>|$_pkg|g")"
                        apply_extra_path_for_targets "$_expanded" "$_targets"
                    done
                    echo "SUSFS_SYNC_INFO: expanded '$_line' over $(printf '%s\n' "$_pkg_list" | wc -l) hidden package(s), hidden from $(printf '%s\n' "$_targets" | wc -l) target(s)"
                else
                    echo "SUSFS_SYNC_WARN: no hidden package to expand '$_line' with (targets.txt/pkgs.txt empty)"
                fi
                ;;
            *)
                apply_extra_path_for_targets "$_line" "$_targets"
                ;;
        esac
    done < "$EXTRA_FILE"
fi

# ABK: per-target hiding (mirrors the API layer per target)
mkdir -p /data/local/tmp/.hma_hf_probe 2>/dev/null
if "$KSU_SUSFS" add_sus_path_hide_from /data/local/tmp/.hma_hf_probe 0 >/dev/null 2>&1; then
    sync_target_hides "$TARGETS_FILE"
else
    echo "SUSFS_SYNC_ERROR: $KSU_SUSFS does not support add_sus_path_hide_from (kernel too old?); per-target hiding skipped"
fi
rmdir /data/local/tmp/.hma_hf_probe 2>/dev/null

echo "SUSFS_SYNC_OK: applied $(wc -l < "$STATE_FILE" 2>/dev/null | tr -d ' ') pair(s), skipped $STATE_SKIPPED already applied ($STATE_MODE)"
exit 0
